// toolsmith-v1: Load Pi coding-agent extensions for a project via Pi's SDK and print the tools they register as JSON (no model call); use to check a Pi extension loads and registers what you expect.
import { existsSync, readdirSync, realpathSync, statSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { dirname, join, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const HELP = ` + "`" + String.raw`pi-ext-tools - list what Pi extensions register, without calling a model.

When to use: you wrote or changed a Pi (earendil-works coding agent) extension
and want to know, without starting an interactive session or spending tokens,
whether it loads and which tools it registers (with descriptions, prompt
snippets/guidelines and whether each tool is active by default). It goes
through Pi's own SDK (DefaultResourceLoader + createAgentSession), so it
resolves imports of @earendil-works/pi-coding-agent, pi-tui and typebox the
way Pi does. It never calls session.prompt and needs no model or auth.

Usage:
  pi-ext-tools <project-dir> [-e <extension-file>]... [--no-global] [--sdk <dir>]

Arguments:
  <project-dir>          Project whose <dir>/.pi/extensions are loaded. It is
                         trusted for this process only (nothing is saved to
                         trust.json).
Options:
  -e, --extension <f>    Extra extension file/dir to load (repeatable).
  --no-global            Don't load extensions from ~/.pi/agent (auto-discovered
                         or configured in settings) nor built-in extensions, and
                         use in-memory settings. Loads only the project's
                         .pi/extensions entries (*.ts, *.js, <dir>/index.ts|js)
                         and the -e files.
  --sdk <dir>            Pi coding-agent package dir. Default: $PI_SDK, else
                         derived from the realpath of the 'pi' binary on PATH.
  -h, --help             Show this help.

Output (stdout, JSON):
  { extensions: [{path, error?}],
    tools: [{name, description, active, source?, promptSnippet?, promptGuidelines?}],
    errors: [...] }
  source is the extension path that registered the tool ("builtin" for core tools).
  Extension console output is redirected to stderr so stdout stays JSON.
Exit: 0 ok; 1 an extension failed to load (or session setup failed); 2 bad usage.

Side effects: none intended on the project. Uses an in-memory session (no
session file). Without --no-global, Pi may refresh packages configured in your
global settings, exactly as starting pi would.

Example:
  pi-ext-tools ./my-project --no-global
  pi-ext-tools . -e ./scratch/my-ext.ts --no-global
` + "`" + String.raw`;

function die(msg, code = 2) {
	process.stderr.write("pi-ext-tools: " + msg + "\n");
	process.exit(code);
}

const argv = process.argv.slice(2);
let projectDir;
const extraExts = [];
let noGlobal = false;
let sdkDir = process.env.PI_SDK;
for (let i = 0; i < argv.length; i++) {
	const a = argv[i];
	if (a === "-h" || a === "--help") { process.stdout.write(HELP); process.exit(0); }
	else if (a === "-e" || a === "--extension") { if (!argv[i + 1]) die(a + " needs a file path."); extraExts.push(resolve(argv[++i])); }
	else if (a === "--no-global") noGlobal = true;
	else if (a === "--sdk") { if (!argv[i + 1]) die("--sdk needs a directory."); sdkDir = argv[++i]; }
	else if (a.startsWith("-")) die("unknown option " + a + ". Run pi-ext-tools --help.");
	else if (!projectDir) projectDir = a;
	else die("unexpected argument " + a + "; only one <project-dir> is accepted.");
}
if (!projectDir) die("missing <project-dir>. Run pi-ext-tools --help.");
projectDir = resolve(projectDir);
if (!existsSync(projectDir) || !statSync(projectDir).isDirectory()) die("project dir not found: " + projectDir);
for (const f of extraExts) if (!existsSync(f)) die("extension file not found: " + f);

if (!sdkDir) {
	let piBin;
	try { piBin = execFileSync("sh", ["-c", "command -v pi"], { encoding: "utf8" }).trim(); } catch {}
	if (!piBin) die("can't find 'pi' on PATH; pass --sdk <pi-coding-agent package dir> or set PI_SDK.");
	// <pkg>/dist/bundle/cli.js or <pkg>/dist/cli.js
	let d = dirname(realpathSync(piBin));
	while (d !== "/" && !existsSync(join(d, "package.json"))) d = dirname(d);
	sdkDir = d;
}
const entry = join(sdkDir, "dist", "index.js");
if (!existsSync(entry)) die("Pi SDK entry not found at " + entry + "; pass --sdk <pi-coding-agent package dir>.");

function projectExtensionPaths(dir) {
	const extDir = join(dir, ".pi", "extensions");
	if (!existsSync(extDir)) return [];
	const out = [];
	for (const name of readdirSync(extDir).sort()) {
		const p = join(extDir, name);
		const st = statSync(p);
		if (st.isFile() && /\.(ts|js|mjs|mts)$/.test(name) && !name.endsWith(".d.ts")) out.push(p);
		else if (st.isDirectory() && ["index.ts", "index.js", "package.json"].some((f) => existsSync(join(p, f)))) out.push(p);
	}
	return out;
}

// Keep stdout clean for JSON: route console output from Pi/extensions to stderr.
const realWrite = process.stdout.write.bind(process.stdout);
const toErr = (...a) => process.stderr.write(a.map(String).join(" ") + "\n");
console.log = console.info = console.debug = toErr;
process.stdout.write = (chunk, ...rest) => process.stderr.write(chunk, ...rest);

const result = { extensions: [], tools: [], errors: [] };
let failed = false;
let session;
try {
	const sdk = await import(pathToFileURL(entry).href);
	const { createAgentSession, DefaultResourceLoader, SessionManager, SettingsManager, getAgentDir } = sdk;
	const agentDir = getAgentDir();
	const settingsManager = noGlobal ? SettingsManager.inMemory() : SettingsManager.create(projectDir, agentDir);
	const loader = new DefaultResourceLoader({
		cwd: projectDir,
		agentDir,
		settingsManager,
		packageCommandOutput: "capture",
		noExtensions: noGlobal,
		additionalExtensionPaths: noGlobal ? [...projectExtensionPaths(projectDir), ...extraExts] : extraExts,
	});
	// Trust the project for this process only (not remembered), so .pi/extensions load.
	await loader.reload({ resolveProjectTrust: async () => true });
	const ext = loader.getExtensions();
	for (const e of ext.extensions) result.extensions.push({ path: e.resolvedPath || e.path });
	for (const e of ext.errors) { result.extensions.push({ path: e.path, error: e.error }); result.errors.push({ type: "extension_load", path: e.path, error: e.error }); failed = true; }
	for (const w of ext.warnings || []) result.errors.push({ type: "extension_warning", path: w.path, warning: w.warning });

	const created = await createAgentSession({
		cwd: projectDir,
		agentDir,
		resourceLoader: loader,
		sessionManager: SessionManager.inMemory(projectDir),
		settingsManager,
	});
	session = created.session;
	const toolSource = new Map();
	for (const e of ext.extensions) for (const name of e.tools.keys()) toolSource.set(name, e.resolvedPath || e.path);
	const active = new Set(session.getActiveToolNames());
	for (const t of session.getAllTools()) {
		const def = session.getToolDefinition(t.name) || {};
		const src = toolSource.get(t.name) || (t.sourceInfo && t.sourceInfo.source !== "builtin" ? t.sourceInfo.path : "builtin");
		const o = { name: t.name, description: t.description, active: active.has(t.name), source: src };
		if (def.promptSnippet) o.promptSnippet = def.promptSnippet;
		if (t.promptGuidelines && t.promptGuidelines.length) o.promptGuidelines = t.promptGuidelines;
		result.tools.push(o);
	}
} catch (err) {
	failed = true;
	result.errors.push({ type: "setup", error: String(err && err.stack ? err.stack.split("\n").slice(0, 3).join(" | ") : err) });
} finally {
	try { session?.dispose(); } catch (e) { result.errors.push({ type: "dispose", error: String(e) }); }
}
realWrite(JSON.stringify(result, null, 2) + "\n", () => process.exit(failed ? 1 : 0));
`);
